package com.example.dashboard.quiz;
import com.auth0.jwt.*;import com.auth0.jwt.algorithms.*;import com.auth0.jwt.exceptions.*;import jakarta.persistence.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.data.jpa.repository.*;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/quizzes") class QuizController{
 private final QuizRepo quizzes;private final AttemptRepo attempts;private final Algorithm jwt;QuizController(QuizRepo q,AttemptRepo a,@Value("${app.jwt.secret}")String s){quizzes=q;attempts=a;jwt=Algorithm.HMAC256(s);}record User(Long id,String role){}record QuestionIn(Long id,String question,List<String> options,Integer correctAnswer){}record QuizIn(String name,String module,String subject,String topic,Integer timeMinutes,List<QuestionIn> questions){}record QuestionView(Long id,String question,List<String> options,Integer correctAnswer){}record QuizView(Long id,String name,String module,String subject,String topic,Integer timeMinutes,List<QuestionView> questions){}record StartView(Long attemptId,QuizView quiz,long remainingSeconds){}record SubmitIn(Map<Long,Integer> answers,Integer warnings){}record Result(Long attemptId,int score,long timeTakenSeconds,int rank,int right,int wrong,int skipped,List<Answer> analysis){}record Answer(Long questionId,Integer selected,Integer correct,boolean right){}
 private User u(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{var t=JWT.require(jwt).withIssuer("dashboard-auth").build().verify(a.substring(7));return new User(Long.valueOf(t.getSubject()),t.getClaim("role").asString());}catch(JWTVerificationException|NumberFormatException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 @PostMapping QuizView create(@RequestHeader(value="Authorization",required=false)String a,@RequestBody QuizIn in){User u=u(a);if(!Set.of("TEACHER","ADMIN").contains(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(in.name()==null||in.name().isBlank()||in.questions()==null||in.questions().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quiz name and questions are required");Quiz q=new Quiz();q.teacherId=u.id;q.name=in.name().trim();q.module=trim(in.module());q.subject=trim(in.subject());q.topic=trim(in.topic());q.timeMinutes=in.timeMinutes();for(QuestionIn x:in.questions()){if(x.question()==null||x.question().isBlank()||x.options()==null||x.options().size()!=4||x.options().stream().anyMatch(v->v==null||v.isBlank())||x.correctAnswer()==null||x.correctAnswer()<0||x.correctAnswer()>=x.options().size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each question needs four options and a correct answer");QuizQuestion z=new QuizQuestion();z.quiz=q;z.question=x.question().trim();z.optionsJson=String.join("\u001F",x.options());z.correctAnswer=x.correctAnswer();q.questions.add(z);}return view(quizzes.save(q),true);}
 private String trim(String value){return value==null?null:value.trim();}
 @GetMapping("/{id}") QuizView get(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){User viewer=u(a);Quiz q=quizzes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return view(q,Set.of("TEACHER","ADMIN").contains(viewer.role));}
 @GetMapping("/admin") List<QuizView> adminList(@RequestHeader(value="Authorization",required=false)String a){if(!"ADMIN".equals(u(a).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return quizzes.findAll().stream().map(q->view(q,true)).toList();}
 @PutMapping("/{id}") @Transactional QuizView edit(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody QuizIn in){
  if(!"ADMIN".equals(u(a).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  Quiz q=quizzes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
  if(in.name()==null||in.name().isBlank()||in.questions()==null||in.questions().isEmpty()||in.timeMinutes()==null||in.timeMinutes()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quiz name, duration, and questions are required");
  for(QuestionIn x:in.questions())if(x.question()==null||x.question().isBlank()||x.options()==null||x.options().size()!=4||x.options().stream().anyMatch(v->v==null||v.isBlank())||x.correctAnswer()==null||x.correctAnswer()<0||x.correctAnswer()>3)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each question needs four options and a correct answer");
  Set<Long> retained=new HashSet<>();for(QuestionIn x:in.questions())if(x.id()!=null){if(!retained.add(x.id())||q.questions.stream().noneMatch(z->x.id().equals(z.id)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Question does not belong to this quiz");}
  q.name=in.name().trim();q.module=trim(in.module());q.subject=trim(in.subject());q.topic=trim(in.topic());q.timeMinutes=in.timeMinutes();
  q.questions.removeIf(x->!retained.contains(x.id));
  for(QuestionIn x:in.questions()){QuizQuestion question=x.id()==null?new QuizQuestion():q.questions.stream().filter(z->x.id().equals(z.id)).findFirst().orElseThrow();question.quiz=q;question.question=x.question().trim();question.optionsJson=String.join("\u001F",x.options());question.correctAnswer=x.correctAnswer();if(x.id()==null)q.questions.add(question);}
  return view(quizzes.save(q),true);
 }
 @DeleteMapping("/{id}") @Transactional void delete(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){if(!"ADMIN".equals(u(a).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Quiz quiz=quizzes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));attempts.deleteAll(attempts.findByQuizId(id));quizzes.delete(quiz);}
 private QuizView view(Quiz q,boolean includeAnswers){return new QuizView(q.id,q.name,q.module,q.subject,q.topic,q.timeMinutes,q.questions.stream().map(item->new QuestionView(item.id,item.question,List.of(item.optionsJson.split("\\u001F",-1)),includeAnswers?item.correctAnswer:null)).toList());}
 @PostMapping("/{id}/start") @Transactional StartView start(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){User u=u(a);if(!"STUDENT".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Quiz q=quizzes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));QuizAttempt at=attempts.findByQuizIdAndStudentIdAndFinishedAtIsNull(id,u.id).orElseGet(()->attempts.save(new QuizAttempt(id,u.id)));long allowed=Math.max(1,Optional.ofNullable(q.timeMinutes).orElse(15))*60L;long remaining=Math.max(0,allowed-Duration.between(at.startedAt,Instant.now()).toSeconds());return new StartView(at.id,view(q,false),remaining);}
 @PostMapping("/attempts/{id}/submit") @Transactional Result submit(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody SubmitIn in){User u=u(a);QuizAttempt at=attempts.findById(id).filter(x->x.studentId.equals(u.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(at.finishedAt!=null)return result(at);at.answersJson=encode(in.answers());at.warnings=Math.min(3,Optional.ofNullable(in.warnings()).orElse(0));at.finishedAt=Instant.now();return result(at);}
 @PostMapping("/attempts/{id}/warning") Result warning(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody SubmitIn in){User u=u(a);QuizAttempt at=attempts.findById(id).filter(x->x.studentId.equals(u.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));at.warnings++;if(at.warnings>=3){at.answersJson=encode(in.answers());at.finishedAt=Instant.now();}attempts.save(at);return at.finishedAt==null?new Result(at.id,0,0,0,0,0,0,List.of()):result(at);}
 @GetMapping("/attempts/{id}/result") Result read(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){User u=u(a);QuizAttempt at=attempts.findById(id).filter(x->x.studentId.equals(u.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(at.finishedAt==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Quiz is still in progress");return result(at);}
 private Result result(QuizAttempt a){Quiz q=quizzes.findById(a.quizId).orElseThrow();Map<Long,Integer> ans=decode(a.answersJson);List<Answer> xs=q.questions.stream().map(x->new Answer(x.id,ans.get(x.id),x.correctAnswer,Objects.equals(ans.get(x.id),x.correctAnswer))).toList();int right=(int)xs.stream().filter(Answer::right).count(), skipped=(int)xs.stream().filter(x->x.selected()==null).count();int rank=1+(int)attempts.findByQuizIdAndFinishedAtIsNotNull(q.id).stream().filter(x->score(x)>right).count();return new Result(a.id,right,Duration.between(a.startedAt,a.finishedAt).toSeconds(),rank,right,xs.size()-right-skipped,skipped,xs);}
 private int score(QuizAttempt a){Quiz q=quizzes.findById(a.quizId).orElseThrow();Map<Long,Integer>x=decode(a.answersJson);return(int)q.questions.stream().filter(z->Objects.equals(x.get(z.id),z.correctAnswer)).count();}private String encode(Map<Long,Integer>x){return x==null?"":x.entrySet().stream().map(e->e.getKey()+":"+e.getValue()).collect(java.util.stream.Collectors.joining(","));}private Map<Long,Integer>decode(String s){Map<Long,Integer>r=new HashMap<>();if(s!=null&&!s.isBlank())for(String x:s.split(",")){String[]p=x.split(":");if(p.length==2)try{r.put(Long.valueOf(p[0]),Integer.valueOf(p[1]));}catch(NumberFormatException ignored){}}return r;}
}
@Entity class Quiz{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long teacherId;public String name;public String module;public String subject;public String topic;public Integer timeMinutes;public Instant createdAt=Instant.now();@OneToMany(mappedBy="quiz",cascade=CascadeType.ALL,orphanRemoval=true)public List<QuizQuestion>questions=new ArrayList<>();}@Entity class QuizQuestion{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;@ManyToOne public Quiz quiz;@Column(length=4000)public String question;@Column(length=8000)public String optionsJson;public Integer correctAnswer;}@Entity class QuizAttempt{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long quizId;public Long studentId;public Instant startedAt=Instant.now();public Instant finishedAt;public int warnings;@Column(length=12000)public String answersJson;QuizAttempt(){}QuizAttempt(Long q,Long s){quizId=q;studentId=s;}}interface QuizRepo extends JpaRepository<Quiz,Long>{}interface AttemptRepo extends JpaRepository<QuizAttempt,Long>{Optional<QuizAttempt>findByQuizIdAndStudentIdAndFinishedAtIsNull(Long q,Long s);List<QuizAttempt>findByQuizIdAndFinishedAtIsNotNull(Long q);List<QuizAttempt>findByQuizId(Long q);}
